-- A claim's external reference (null when none was given), kept as typed with its surrounding spaces removed. No two
-- claims of a sheet share one, comparing without regard to case: ref_key is the reference in lower case.
ALTER TABLE claim ADD COLUMN ref VARCHAR(250);
ALTER TABLE claim ADD COLUMN ref_key VARCHAR(250);
CREATE UNIQUE INDEX claim_ref_unique ON claim (sheet_id, ref_key);
ALTER TABLE claim_edit ADD COLUMN ref VARCHAR(250);
-- A person's claims. The id is assigned by the store, so it orders claims as they were added.
-- The amount is kept exactly, with two decimals; the date is the claim's own (the sheet's today
-- when none was given); the note may be empty.
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200)   NOT NULL,
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(19, 2) NOT NULL,
    claim_date DATE           NOT NULL,
    note       VARCHAR(2000)  NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, person_id, id);
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A claim of a person on a sheet: an amount (two decimals; negative only for a correction), a date, a note (may be empty), its status
 * its number (given when opened; kept when voided; null for a draft) and its due fixed when settled (null when not
 * settled, or settled while its grade had no rate), who opened it (null when never opened),
 * whether it is bound to the figure it had at its person's last statement ({@code stated}) and that figure
 * ({@code statedDue}; null when it had none), and for a correction (a negative amount) the number of the SETTLED
 * claim of the same person it corrects ({@code corrects}; null for any other claim), and its due-by ({@code dueBy}), fixed
 * when it is added from its person's own terms, else those of their grade in force on its date (see SettingRepository#terms), and the
 * date it is deferred until ({@code deferredUntil}; null when never deferred; see ClaimDue#deferred), and its proofs
 * count ({@code proofs}; 0 when added, raised by one at a time; see ApplyProof), and for a claim split off another
 * the number of the claim it was split from ({@code splitFrom}; null for any other claim; see ApplySplit), and its external
 * reference ({@code ref}; surrounding spaces removed; null when none was given), no two of a sheet's claims sharing one in any case.
 */
public record Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
        ClaimStatus status, String number, BigDecimal due, String openedBy, boolean stated, BigDecimal statedDue,
        String corrects, LocalDate dueBy, LocalDate deferredUntil, int proofs,
        String splitFrom, String ref) {
}
package net.officefloor.hq.app.claim;

/** Body of an add or edit of a claim, and who makes it. A blank date takes the sheet's today; corrects is the number of the
 *  claim a correction corrects (blank: none); ref is its external reference (blank: none). */
public record ClaimRequest(String amount, String date, String note, String corrects, String by, String ref) {
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.List;

/** A claim as sent to the screen: the amount as text with two decimals, so it is never rounded through a float;
 *  the number is null when the claim has none; due is the due fixed when settled (two decimals), null while it is
 *  live; openedBy is who opened it, null when never opened; stated is whether it is bound to the figure statedDue
 *  (two decimals, null when it had none) by its person's last statement; corrects is the number of the claim a
 *  correction corrects (null for any other claim); roundsOn is the date that decides how its live figures round
 *  (the corrected claim's date for a correction, else its own; see Rounding); dueBy (yyyy-MM-dd) is its due-by, fixed
 *  when it was added; deferred is whether it is deferred on the sheet's today (see ClaimDue#deferred) and deferredUntil
 *  (yyyy-MM-dd) the date it was last deferred until (shown even once that date has passed), null when never deferred; proofs is its proofs count; splitFrom is the number of the claim it was split from (null for any other claim); log is its status log, oldest first: each status it has had, who made the change, the sheet's
 *  today (yyyy-MM-dd) then, and its due as shown at that moment (two decimals, or n/a); lockedBy is who has its editor
 *  open (null when no one does); lateEntry is whether it was added while its period was soft-closed; reminded (yyyy-MM-dd) is the last day a
 *  reminder was written for it, null when none; ref is its external reference, null when none. */
public record ClaimResponse(long id, String sheetId, long personId, String amount, String date, String note,
        String status, String number, String due, String openedBy, boolean stated, String statedDue, String corrects,
        String roundsOn, String dueBy, boolean deferred, String deferredUntil, int proofs, String splitFrom, List<LogLine> log,
        String lockedBy, boolean lateEntry, String reminded, String ref) {

    /** One line of a claim's status log as sent to the screen. */
    public record LogLine(String status, String by, String date, String due) {
    }

    public static ClaimResponse from(Claim claim, ClaimRepository claims, ClaimLogRepository log, LocalDate today) {
        return from(claim, claims, log.of(claim.sheetId(), claim.id()), today);
    }

    public static ClaimResponse from(Claim claim, ClaimRepository claims, List<ClaimLogLine> log, LocalDate today) {
        return from(claim, claims, log, today, claims.lockedBy(claim.sheetId(), claim.id()),
                claims.lateEntry(claim.sheetId(), claim.id()), claims.remindedOn(claim.sheetId(), claim.id()));
    }

    public static ClaimResponse from(Claim claim, ClaimRepository claims, List<ClaimLogLine> log, LocalDate today, String lockedBy,
            boolean lateEntry, LocalDate reminded) {
        boolean deferred = ClaimDue.deferred(claim, today);
        return new ClaimResponse(claim.id(), claim.sheetId(), claim.personId(), claim.amount().toPlainString(),
                claim.date().toString(), claim.note(), claim.status().name(), claim.number(),
                claim.due() == null ? null : claim.due().toPlainString(), claim.openedBy(), claim.stated(),
                claim.statedDue() == null ? null : claim.statedDue().toPlainString(), claim.corrects(),
                Rounding.roundsOn(claim, claims).toString(), claim.dueBy().toString(),
                deferred, claim.deferredUntil() == null ? null : claim.deferredUntil().toString(), claim.proofs(), claim.splitFrom(),
                log.stream().map((l) -> new LogLine(l.status().name(), l.by(), l.date().toString(), l.due())).toList(),
                lockedBy, lateEntry, reminded == null ? null : reminded.toString(), claim.ref());
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Locale;
import java.util.regex.Pattern;

/** A claim's values once validated. {@code date} is null when none was given (the sheet's today applies). {@code corrects} is the number of
 *  the claim a correction corrects (null when none was given). {@code by} is who gives them. {@code ref} is its external reference,
 *  surrounding spaces removed (null when none, or a blank one, was given). */
public record ClaimValues(BigDecimal amount, LocalDate date, String note, String corrects, String by, String ref) {
    private static final Pattern AMOUNT = Pattern.compile("-?\\d{1,15}(\\.\\d{1,2})?");

    /** The request's values by the claim form's rules (see ValidateClaim). */
    public static ClaimValues from(ClaimRequest request) throws InvalidClaimException {
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("The amount must be a number with up to two decimals");
        }
        String date = request.date() == null ? "" : request.date().trim();
        LocalDate parsed = null;
        if (!date.isEmpty()) {
            try {
                parsed = LocalDate.parse(date);
            } catch (DateTimeParseException e) {
                throw new InvalidClaimException("The date must be yyyy-MM-dd");
            }
        }
        String note = request.note() == null ? "" : request.note().trim();
        String corrects = request.corrects() == null ? "" : request.corrects().trim();
        String ref = request.ref() == null ? "" : request.ref().trim();
        return new ClaimValues(new BigDecimal(amount).setScale(2), parsed, note, corrects.isEmpty() ? null : corrects,
                request.by() == null ? "" : request.by().trim(), ref.isEmpty() ? null : ref);
    }

    /** The reference as compared: without regard to case. */
    public static String refKey(String ref) {
        return ref == null ? null : ref.toLowerCase(Locale.ROOT);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Adds the claim to the person; a claim given no date is dated the sheet's entry date, else its today. A claim whose due-by falls inside
 *  a closed period, or dated after the person's retirement date, is refused, as is a
 *  negative amount that does not correct a SETTLED claim of the person (see Corrections). Its due-by is fixed here: its
 *  terms-th business day after its date (see ClaimRules.dueBy). A claim whose due-by falls inside a soft-closed period is
 *  marked a late entry. Its status log starts with its DRAFT line (see ClaimLog). */
public class AddClaim {
    public void add(@Val Person person, @Val ClaimValues values, ClaimRepository claims,
            PeriodRepository periods, SettingRepository settings, HolidayRepository holidays, ClaimLog log, Out<Claim> claim) throws InvalidClaimException {
        ClaimRules.Checked checked = ClaimRules.check(person, values, settings, periods, claims, holidays);
        LocalDate date = checked.date();
        Claim added = claims.add(person.sheetId(), person.id(), values.amount(), date, values.note(), checked.corrects(),
                values.ref(), checked.dueBy());
        log.write(added, values.by());
        if (periods.softClosedOn(added.sheetId(), checked.dueBy())) {
            claims.markLateEntry(added);
        }
        claim.set(added);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Applies the edited values; only a DRAFT claim can be edited (an open claim is voided and a new one added instead),
 * and a claim whose due-by (which an edit leaves as it is) falls inside a closed period, or left or moved after its person's retirement date,
 * is refused, as is a reference another claim of the sheet already has (see ClaimRules.checkRef). */
public class ApplyClaim {
    public void apply(@Val Claim claim, @Val ClaimValues values, SheetRepository sheets, PeriodRepository periods,
            PersonRepository people, ClaimRepository claims, Out<Claim> changed) throws InvalidClaimException {
        if (claim.status() != ClaimStatus.DRAFT) {
            throw new InvalidClaimException("Only a DRAFT claim can be edited");
        }
        LocalDate date = values.date() != null ? values.date() : sheets.today(claim.sheetId());
        if (periods.closedOn(claim.sheetId(), claim.dueBy())) {
            throw new InvalidClaimException("The claim's due-by is inside a closed period");
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        if (person != null && !person.mayClaimOn(date)) {
            throw new InvalidClaimException("The claim's date is after the person's retirement date");
        }
        ClaimRules.checkRef(claim.sheetId(), values, claim.id(), claims);
        changed.set(new Claim(claim.id(), claim.sheetId(), claim.personId(), values.amount(), date, values.note(), claim.status(),
                claim.number(), claim.due(), claim.openedBy(), claim.stated(), claim.statedDue(),
                Corrections.check(claim.sheetId(), claim.personId(), values, claims), claim.dueBy(), claim.deferredUntil(), claim.proofs(), claim.splitFrom(), values.ref()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Writes CLAIM_ADDED to the audit file (with ref=<reference> at its end when the claim has one) once the claim is stored, then LATE_ENTRY for a late entry (see AddClaim). Then writes the
 * figures the change moved (see Rollup). */
public class RecordClaimAdded {
    public void record(@Val Claim claim, @Val Person person, @Val ClaimValues values, @Val RollupBefore before, ClaimRepository claims, Rollup rollup, Audit audit) {
        audit.record("CLAIM_ADDED sheet=" + claim.sheetId() + " by=" + values.by() + " person=" + person.name()
                + " amount=" + claim.amount().toPlainString() + " date=" + claim.date()
                + (claim.ref() == null ? "" : " ref=" + claim.ref()));
        if (claims.lateEntry(claim.sheetId(), claim.id())) {
            audit.record("LATE_ENTRY sheet=" + claim.sheetId() + " by=" + values.by() + " person=" + person.name()
                    + " amount=" + claim.amount().toPlainString() + " date=" + claim.date());
        }
        rollup.record(claim.sheetId(), values.by(), before);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Takes the split amount off the claim: it keeps the rest of its amount and loses any figure a statement bound it to.
 * Only an OPEN claim that is not deferred (see ClaimDue#deferred) nor whose due-by falls inside a closed period is split, only by
 * an amount more than 0.00 and less than its amount, and only by a user whose role the sheet lets open a claim (the
 * new claim is theirs to open; see SettingRepository#permits).
 */
public class ApplySplit {
    public void apply(@Val Claim claim, @Val ClaimSplit split, SheetRepository sheets, PeriodRepository periods,
            SettingRepository settings, RoleRepository roles, Out<Claim> changed) throws InvalidClaimStatusException {
        if (claim.status() != ClaimStatus.OPEN) {
            throw new InvalidClaimStatusException("Only an OPEN claim can be split");
        }
        if (ClaimDue.deferred(claim, sheets.today(claim.sheetId()))) {
            throw new InvalidClaimStatusException("A deferred claim cannot be split");
        }
        if (periods.closedOn(claim.sheetId(), claim.dueBy())) {
            throw new InvalidClaimStatusException("The claim's due-by is inside a closed period");
        }
        if (split.amount().signum() <= 0 || split.amount().compareTo(claim.amount()) >= 0) {
            throw new InvalidClaimStatusException("A split takes more than 0.00 and less than the claim's amount");
        }
        String role = roles.roleOf(claim.sheetId(), split.by());
        if (!settings.permits(claim.sheetId(), "open", role)) {
            throw new InvalidClaimStatusException("A " + role + " may not open a claim");
        }
        changed.set(new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount().subtract(split.amount()),
                claim.date(), claim.note(), claim.status(), claim.number(), claim.due(), claim.openedBy(), false, null,
                claim.corrects(), claim.dueBy(), claim.deferredUntil(), claim.proofs(), claim.splitFrom(), claim.ref()));
    }
}
package net.officefloor.hq.app.claim;

/** The new claim a split made, as stored (the claim it was split from stays the pipeline's Claim). */
public record SplitOff(Claim claim) {
}

