import { live, useClaims, type ClaimStatus } from '../claims/claims';
import { overdue } from '../overdue/overdue';
import { usePeople } from '../people/people';
import { personDue, personSplit, sum, trimmedSum, useRates } from '../rates/rates';
import { useCap, useFloor, useLate } from '../settings/settings';

// The sheet-wide figures shown in more than one place (the rollups, the summary and the header), worked out once
// here so every place that shows one shows the same value.

/** The statuses claims are counted by. */
export const STATUSES: readonly ClaimStatus[] = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'];

/** The sheet's due-total: everyone's due-total added up, skipping n/a, leaving out the single highest and lowest
 *  when three or more people have one. */
export function useSheetDueTotal(sheetId: string): string {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const late = useLate(sheetId);
  const floor = useFloor(sheetId);
  const cap = useCap(sheetId);
  return trimmedSum(
    (people.data ?? []).map((p) =>
      personDue(live(claims.data?.filter((c) => c.personId === p.id) ?? [], [p], late.today), rates.data, p, late, floor, cap),
    ),
  );
}

/** The sheet's settled-total and open-total: everyone's added up (not trimmed). */
export function useSheetSplit(sheetId: string): { settled: string; open: string } {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const late = useLate(sheetId);
  const floor = useFloor(sheetId);
  const all = (people.data ?? []).map((p) =>
    personSplit(live(claims.data?.filter((c) => c.personId === p.id) ?? [], [p], late.today), rates.data, p, late, floor),
  );
  return { settled: sum(all.map((s) => s.settled)), open: sum(all.map((s) => s.open)) };
}

/** The sheet's overdue count and overdue-total: everyone's added up (the total leaving out the single highest and
 *  lowest when there are three or more people). */
export function useSheetOverdue(sheetId: string): { count: number; total: string } {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const all = (people.data ?? []).map((p) =>
    overdue(live(claims.data?.filter((c) => c.personId === p.id) ?? [], [p], late.today), rates.data, p, late, floor),
  );
  return { count: all.reduce((n, o) => n + o.count, 0), total: trimmedSum(all.map((o) => o.total)) };
}

/** How many of the sheet's claims have each status. */
export function useStatusCounts(sheetId: string): (status: ClaimStatus) => number {
  const claims = useClaims(sheetId);
  return (status) => (claims.data ?? []).filter((c) => c.status === status).length;
}
import { useEffect, useRef, useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson, putJson } from '../../api/http';
import { PeopleHead, PersonRow } from '../../slots/defs/personRow';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPage } from '../../slots/defs/sheetPage';
import { gradeOn, usePeople, type Person } from '../people/people';
import { periodOf, usePeriods } from '../periods/periods';
import { useRoles } from '../roles/roles';
import { claimDue, rateFor, useRates } from '../rates/rates';
import { dueBy, isOverdue } from '../overdue/overdue';
import { useFloor, useLate, type Dated } from '../settings/settings';
import { claimsKey, live, logLine, total, useClaims, type Claim } from './claims';
import { useSelectedClaims } from './selection';
import { useSheetToday } from '../session/session';

type Values = { amount: string; date: string; note: string; corrects: string; ref: string };
const EMPTY: Values = { amount: '', date: '', note: '', corrects: '', ref: '' };

function ClaimsHead() {
  return (
    <>
      <th>Claimed</th>
      <th>Claims</th>
    </>
  );
}

const DRAFT_ONLY = 'Only a draft claim whose due-by is not inside a closed period can be edited; void it and add a new one instead.';
const VIEWER_REFUSED = 'A viewer cannot change the sheet.';
const LOCK_REFUSED = 'Someone else is editing this claim; it can be edited once they save or cancel.';
const EDIT_REFUSED = 'This claim cannot be edited: only a draft whose due-by is not inside a closed period, and not while someone else is editing it.';

type Action = 'open' | 'settle' | 'approve' | 'reject' | 'void' | 'resettle';

/** One claim: its select checkbox (the selection a bulk action takes), its values, status, due, its status log (oldest first), due-by (fixed when it was added), whether it is overdue, whether it is deferred and until when, its proofs count, and the period its due-by falls in, with the buttons that edit it or change its status. A clerk's settle above the clerk limit makes it PENDING; a
 *  steward approves it, or rejects it with the reason typed beside Reject. An action the status does not allow,
 *  settling or approving a claim the user opened, or a clerk approving or rejecting, is refused by the server and
 *  shows the claim's error. An OPEN claim is deferred until the date typed beside Defer (after today; refused, with the claim's error, for any other claim or date). Add proof raises its proofs count by one (refused, with the claim's error, for a SETTLED or VOID claim or one whose due-by is inside a closed period); a claim with no proofs whose due is above the proof threshold on its date cannot be settled nor approved; a claim with an empty note whose due is above the note threshold on its date cannot be opened (alone or in bulk). A steward voids a SETTLED claim within 7 days of its settlement (its frozen figure leaves every total). A steward re-settles a SETTLED claim (its due fixed again at today's figure). A steward re-dates an OPEN or PENDING claim to the date typed beside Re-date (its due-by and any statement figure stay; refused, with the claim's error, for anyone else, any other claim, or a date after the person's retirement). A steward moves a DRAFT, OPEN or PENDING claim to the person picked beside Move (refused,
 *  with the claim's error, for anyone else or any other claim). Remind writes a reminder for an OPEN or PENDING claim, once per sheet-today, which becomes its reminded date (refused, with the claim's error, for any other claim or a second reminder that day). Split takes the amount typed beside it off an OPEN claim (not deferred, nor with its due-by inside a closed period; more than 0.00 and less than its amount; only by a role the sheet lets open a claim) into a new OPEN claim of the person, refused with the claim's error otherwise. Only a DRAFT whose due-by is not inside a closed period can be edited: Edit opens the editor and locks the claim for the user until it
 *  is saved or cancelled (Cancel) or the sheet's today changes; Edit on any other claim, on a claim another user holds, or by a
 *  viewer shows the claim's error instead and takes no lock. The row's own amount entry and Save amount change a DRAFT's amount
 *  exactly as the editor's save would (same rules, CLAIM_EDITED), keeping its date and note; a refusal shows the claim's error. */
function ClaimRow({
  sheetId,
  user,
  claim: c,
  rate,
  floor,
  editing,
  onEdit,
  onCancel,
}: {
  sheetId: string;
  user: string;
  claim: Claim;
  rate: string | undefined;
  floor: Dated;
  editing: boolean;
  onEdit: () => void;
  onCancel: () => void;
}) {
  const roles = useRoles(sheetId);
  const viewer = roles.data?.find((r) => r.user === user)?.role === 'viewer';
  const queryClient = useQueryClient();
  const periods = usePeriods(sheetId);
  const late = useLate(sheetId);
  const status = useMutation({
    mutationFn: (action: Action) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${c.id}/status`, {
        action,
        by: user,
        reason: action === 'reject' ? reason : '',
      }),
    onSuccess: (_, action) => {
      if (action === 'reject') setReason('');
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });
  const people = usePeople(sheetId);
  const [moveTo, setMoveTo] = useState('');
  const reassign = useMutation({
    mutationFn: (personId: number) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${c.id}/person`, { personId, by: user }),
    onSuccess: () => {
      setMoveTo('');
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });
  const [reason, setReason] = useState('');
  const [deferUntil, setDeferUntil] = useState('');
  const defer = useMutation({
    mutationFn: (until: string) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${c.id}/defer`, { until, by: user }),
    onSuccess: () => {
      setDeferUntil('');
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });
  const [newDate, setNewDate] = useState('');
  const redate = useMutation({
    mutationFn: (date: string) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${c.id}/date`, { date, by: user }),
    onSuccess: () => {
      setNewDate('');
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });
  const proof = useMutation({
    mutationFn: () => postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${c.id}/proofs`, { by: user }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
  });
  const [splitAmount, setSplitAmount] = useState('');
  const split = useMutation({
    mutationFn: (amount: string) =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${c.id}/split`, { amount, by: user }),
    onSuccess: () => {
      setSplitAmount('');
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });
  const remind = useMutation({
    mutationFn: () => postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${c.id}/remind`, { by: user }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
  });
  const [inlineAmount, setInlineAmount] = useState('');
  // the row's own amount entry saves through the claim form's edit, keeping the claim's date, note, corrects and reference
  const inline = useMutation({
    mutationFn: (amount: string) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${c.id}`, {
        amount,
        date: c.date,
        note: c.note,
        corrects: c.corrects ?? '',
        ref: c.ref ?? '',
        by: user,
      }),
    onSuccess: () => {
      setInlineAmount('');
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });
  const [editRefused, setEditRefused] = useState<string | null>(null);
  const lock = useMutation({
    mutationFn: () => putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${c.id}/lock`, { by: user }),
    onSuccess: () => {
      onEdit();
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onError: (e) => setEditRefused(e instanceof HttpError && e.status === 403 ? VIEWER_REFUSED : EDIT_REFUSED),
  });
  const [selected, setSelected] = useSelectedClaims();
  const act = (action: Action) => {
    setEditRefused(null);
    lock.reset();
    reassign.reset();
    defer.reset();
    redate.reset();
    proof.reset();
    split.reset();
    remind.reset();
    inline.reset();
    status.reset();
    status.mutate(action);
  };

  return (
    <li data-testid={`claim-row-${c.id}`}>
      <input
        type="checkbox"
        data-testid="claim-select"
        aria-label="Select claim"
        checked={selected.includes(c.id)}
        onChange={(e) => setSelected(e.target.checked ? [...selected, c.id] : selected.filter((id) => id !== c.id))}
      />{' '}
      <span data-testid="claim-number">{c.number ?? ''}</span>{' '}
      <span data-testid="claim-amount">{c.amount}</span> <span data-testid="claim-date">{c.date}</span>{' '}
      <span data-testid="claim-note">{c.note}</span>{' '}
      <span data-testid="claim-due">{claimDue(c, rate, floor, late)}</span>{' '}
      <span data-testid="claim-due-by">{dueBy(c)}</span>{' '}
      <span data-testid="claim-overdue">{isOverdue(c, late) ? 'yes' : 'no'}</span>{' '}
      <span data-testid="claim-status">{c.status}</span>{' '}
      <span data-testid="claim-opened-by">{c.openedBy ?? ''}</span>{' '}
      <span data-testid="claim-stated">{c.stated ? 'yes' : 'no'}</span>{' '}
      <span data-testid="claim-corrects">{c.corrects ?? ''}</span>{' '}
      <span data-testid="claim-ref">{c.ref ?? ''}</span>{' '}
      <span data-testid="claim-deferred">{c.deferred ? 'yes' : 'no'}</span>{' '}
      <span data-testid="claim-deferred-until">{c.deferredUntil ?? ''}</span>{' '}
      <span data-testid="claim-proofs">{c.proofs}</span>{' '}
      <span data-testid="claim-split-from">{c.splitFrom ?? ''}</span>{' '}
      <span data-testid="claim-late-entry">{c.lateEntry ? 'yes' : 'no'}</span>{' '}
      <span data-testid="claim-reminded">{c.reminded ?? ''}</span>{' '}
      <span data-testid="claim-period">{periodOf(periods.data, c.dueBy)?.name ?? ''}</span>{' '}
      <button
        type="button"
        data-testid="claim-edit"
        onClick={() => {
          status.reset();
          reassign.reset();
          defer.reset();
          redate.reset();
          proof.reset();
          split.reset();
          remind.reset();
          inline.reset();
          lock.reset();
          setEditRefused(null);
          // refused at once when the screen already knows the claim cannot be edited; else the server decides
          if (c.status !== 'DRAFT' || periodOf(periods.data, c.dueBy)?.closed) {
            setEditRefused(DRAFT_ONLY);
            return;
          }
          if (viewer) {
            setEditRefused(VIEWER_REFUSED);
            return;
          }
          if (c.lockedBy && c.lockedBy !== user) {
            setEditRefused(LOCK_REFUSED);
            return;
          }
          lock.mutate();
        }}
        disabled={lock.isPending}
      >
        Edit
      </button>
      {editing && (
        <button type="button" data-testid="claim-cancel" onClick={onCancel}>
          Cancel
        </button>
      )}{' '}
      <input
        data-testid="claim-inline-amount"
        placeholder="Amount"
        inputMode="decimal"
        value={inlineAmount}
        onChange={(e) => {
          setInlineAmount(e.target.value);
          inline.reset();
        }}
      />
      <button
        type="button"
        data-testid="claim-inline-save"
        disabled={inline.isPending}
        onClick={() => {
          setEditRefused(null);
          lock.reset();
          status.reset();
          reassign.reset();
          defer.reset();
          redate.reset();
          proof.reset();
          split.reset();
          remind.reset();
          inline.reset();
          inline.mutate(inlineAmount);
        }}
      >
        Save amount
      </button>{' '}
      <button type="button" data-testid="claim-open" disabled={status.isPending} onClick={() => act('open')}>
        Open
      </button>
      <button type="button" data-testid="claim-settle" disabled={status.isPending} onClick={() => act('settle')}>
        Settle
      </button>
      <button type="button" data-testid="claim-approve" disabled={status.isPending} onClick={() => act('approve')}>
        Approve
      </button>
      <input
        data-testid="claim-reject-reason"
        placeholder="Reason"
        value={reason}
        onChange={(e) => {
          setReason(e.target.value);
          status.reset();
        }}
      />
      <button type="button" data-testid="claim-reject" disabled={status.isPending} onClick={() => act('reject')}>
        Reject
      </button>
      <button type="button" data-testid="claim-void" disabled={status.isPending} onClick={() => act('void')}>
        Void
      </button>
      <button type="button" data-testid="claim-resettle" disabled={status.isPending} onClick={() => act('resettle')}>
        Re-settle
      </button>
      <button
        type="button"
        data-testid="claim-proof"
        disabled={proof.isPending}
        onClick={() => {
          setEditRefused(null);
          lock.reset();
          status.reset();
          reassign.reset();
          defer.reset();
          redate.reset();
          proof.reset();
          split.reset();
          remind.reset();
          inline.reset();
          proof.mutate();
        }}
      >
        Add proof
      </button>
      <input
        type="date"
        data-testid="claim-defer-date"
        aria-label="Defer until"
        value={deferUntil}
        onChange={(e) => {
          setDeferUntil(e.target.value);
          defer.reset();
          redate.reset();
          proof.reset();
          split.reset();
          remind.reset();
          inline.reset();
        }}
      />
      <button
        type="button"
        data-testid="claim-defer"
        disabled={defer.isPending}
        onClick={() => {
          setEditRefused(null);
          lock.reset();
          status.reset();
          reassign.reset();
          defer.reset();
          redate.reset();
          proof.reset();
          split.reset();
          remind.reset();
          inline.reset();
          defer.mutate(deferUntil.trim());
        }}
      >
        Defer
      </button>{' '}
      <input
        type="date"
        data-testid="claim-date-new"
        aria-label="New date"
        value={newDate}
        onChange={(e) => {
          setNewDate(e.target.value);
          redate.reset();
        }}
      />
      <button
        type="button"
        data-testid="claim-redate"
        disabled={redate.isPending}
        onClick={() => {
          setEditRefused(null);
          lock.reset();
          status.reset();
          reassign.reset();
          defer.reset();
          redate.reset();
          proof.reset();
          split.reset();
          remind.reset();
          inline.reset();
          redate.mutate(newDate.trim());
        }}
      >
        Re-date
      </button>{' '}
      <input
        data-testid="claim-split-amount"
        placeholder="Split amount"
        inputMode="decimal"
        value={splitAmount}
        onChange={(e) => {
          setSplitAmount(e.target.value);
          split.reset();
          remind.reset();
          inline.reset();
        }}
      />
      <button
        type="button"
        data-testid="claim-split"
        disabled={split.isPending}
        onClick={() => {
          setEditRefused(null);
          lock.reset();
          status.reset();
          reassign.reset();
          defer.reset();
          redate.reset();
          proof.reset();
          split.reset();
          remind.reset();
          inline.reset();
          split.mutate(splitAmount.trim());
        }}
      >
        Split
      </button>{' '}
      <select
        data-testid="claim-reassign-to"
        aria-label="Move to"
        value={moveTo}
        onChange={(e) => {
          setMoveTo(e.target.value);
          reassign.reset();
        }}
      >
        <option value="">Move to…</option>
        {(people.data ?? [])
          .filter((p) => p.id !== c.personId)
          .map((p) => (
            <option key={p.id} value={String(p.id)}>
              {p.name}
            </option>
          ))}
      </select>
      <button
        type="button"
        data-testid="claim-reassign"
        disabled={reassign.isPending || moveTo === ''}
        onClick={() => {
          setEditRefused(null);
          lock.reset();
          status.reset();
          reassign.reset();
          defer.reset();
          redate.reset();
          proof.reset();
          split.reset();
          remind.reset();
          inline.reset();
          reassign.mutate(Number(moveTo));
        }}
      >
        Move
      </button>{' '}
      <button
        type="button"
        data-testid="claim-remind"
        disabled={remind.isPending}
        onClick={() => {
          setEditRefused(null);
          lock.reset();
          status.reset();
          reassign.reset();
          defer.reset();
          redate.reset();
          proof.reset();
          split.reset();
          remind.reset();
          inline.reset();
          remind.mutate();
        }}
      >
        Remind
      </button>
      {editRefused !== null && <span data-testid="claim-error"> {editRefused}</span>}
      {status.isError && (
        <span data-testid="claim-error">
          {' '}
          {(c.status === 'OPEN' || c.status === 'PENDING') && c.openedBy === user && status.variables !== 'reject' && status.variables !== 'void' && status.variables !== 'resettle'
            ? 'You opened this claim, so someone else must settle or approve it.'
            : `A ${c.status} claim cannot be changed that way, nor one whose due-by is inside a closed period, nor a deferred one settled, nor one with no proofs settled or approved when its due is above the proof threshold, nor one with an empty note opened when its due is above the note threshold; only a steward approves or rejects a pending claim or re-settles a settled one, only a steward voids a settled claim and only within 7 days of its settlement, a rejection needs a reason, and only a role the sheet lets open, settle or void a claim may do so.`}
        </span>
      )}
      {reassign.isError && (
        <span data-testid="claim-error">
          {' '}
          Only a role the sheet lets reassign (a steward unless set) moves a claim, and only a draft, open or pending one (not a correction, nor one whose due-by is inside a
          closed period) to another person not retired before its date.
        </span>
      )}
      {defer.isError && (
        <span data-testid="claim-error">
          {' '}
          Only an open claim whose due-by is not inside a closed period can be deferred, and only to a date after today.
        </span>
      )}
      {redate.isError && (
        <span data-testid="claim-error">
          {' '}
          Only a steward re-dates a claim, and only an open or pending one whose due-by is not inside a closed period, to a date
          not after the person's retirement.
        </span>
      )}
      {proof.isError && (
        <span data-testid="claim-error"> A settled or void claim, or one whose due-by is inside a closed period, takes no more proofs.</span>
      )}
      {split.isError && (
        <span data-testid="claim-error">
          {' '}
          Only an open claim, not deferred, nor with its due-by inside a closed period, can be split, by an amount more than 0.00 and less than
          its amount, and only by a role the sheet lets open a claim.
        </span>
      )}
      {remind.isError && (
        <span data-testid="claim-error">
          {' '}
          Only an open or pending claim can be reminded, and only once a day.
        </span>
      )}
      {inline.isError && (
        <span data-testid="claim-error">
          {' '}
          {inline.error instanceof HttpError && inline.error.status === 403
            ? VIEWER_REFUSED
            : 'Only a draft claim whose due-by is not inside a closed period, and that no one else is editing, can have its amount changed, to one with up to two decimals, 0.00 or more unless it corrects a settled claim.'}
        </span>
      )}
      <ol data-testid="claim-log">
        {c.log.map((l, i) => (
          <li key={i} data-testid="claim-log-line">
            {logLine(l)}
          </li>
        ))}
      </ol>
    </li>
  );
}

/** A person's claimed, and their claims (newest first) with the form that adds one or saves the one
 *  being edited. A blank date takes the sheet's entry date, else its today (the server applies it). */
function PersonClaims({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId).data;
  const floor = useFloor(sheetId);
  const today = useSheetToday(sheetId);
  const queryClient = useQueryClient();
  const mine = claims.data?.filter((c) => c.personId === person.id) ?? [];
  const [editingId, setEditingId] = useState<number | undefined>(undefined);
  const [values, setValues] = useState<Values>(EMPTY);
  const unlock = useMutation({
    mutationFn: (id: number) => putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${id}/unlock`, { by: user }),
    onSettled: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
  });

  const submit = useSubmitOnce();
  const save = useMutation({
    mutationFn: ({ id, ...v }: Values & { id?: number }) => {
      const base = `/api/sheets/${encodeURIComponent(sheetId)}`;
      const body = { ...v, by: user };
      return id === undefined
        ? postJson<Claim>(`${base}/people/${person.id}/claims`, body)
        : putJson<Claim>(`${base}/claims/${id}`, body);
    },
    onSuccess: () => {
      setValues(EMPTY);
      setEditingId(undefined);
      void queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onSettled: submit.end,
  });

  const change = (v: Partial<Values>) => {
    setValues((was) => ({ ...was, ...v }));
    save.reset();
  };
  const openEditor = (c: Claim) => {
    save.reset();
    if (editingId !== undefined && editingId !== c.id) unlock.mutate(editingId);
    setValues({ amount: c.amount, date: c.date, note: c.note, corrects: c.corrects ?? '', ref: c.ref ?? '' });
    setEditingId(c.id);
  };
  const cancel = () => {
    save.reset();
    if (editingId !== undefined) unlock.mutate(editingId);
    setValues(EMPTY);
    setEditingId(undefined);
  };

  // The editor of a claim the user still holds (its lock outlived a reload of the sheet) opens again once the claims
  // are read fresh, so it can be saved or cancelled.
  const restored = useRef(false);
  useEffect(() => {
    if (restored.current || claims.data === undefined || claims.isFetching) return;
    restored.current = true;
    const held = mine.find((c) => c.lockedBy === user && c.status === 'DRAFT');
    if (held !== undefined && editingId === undefined) openEditor(held);
  });

  return (
    <>
      <td data-testid="person-claimed">{total(live(mine, [person], today))}</td>
      <td>
        <form
          data-testid="claim-form"
          onSubmit={(e) => {
            e.preventDefault();
            if (!submit.begin()) return;
            save.reset();
            save.mutate({ ...values, id: editingId });
          }}
        >
          <input
            data-testid="claim-form-amount"
            placeholder="Amount"
            inputMode="decimal"
            value={values.amount}
            onChange={(e) => change({ amount: e.target.value })}
          />{' '}
          <input type="date" data-testid="claim-form-date" value={values.date} onChange={(e) => change({ date: e.target.value })} />{' '}
          <input data-testid="claim-form-note" placeholder="Note" value={values.note} onChange={(e) => change({ note: e.target.value })} />{' '}
          <input
            data-testid="claim-form-corrects"
            placeholder="Corrects no."
            inputMode="numeric"
            value={values.corrects}
            onChange={(e) => change({ corrects: e.target.value })}
          />{' '}
          <input data-testid="claim-form-ref" placeholder="Reference" value={values.ref} onChange={(e) => change({ ref: e.target.value })} />{' '}
          <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
            {editingId === undefined ? 'Add claim' : 'Save claim'}
          </button>
          {save.isError && (
            <span data-testid="claim-form-error">
              The amount must have up to two decimals, and be 0.00 or more unless it corrects, by number, a settled claim of this person; its due-by not inside a closed period, the date not after the person's retirement date, the reference not one already used on the sheet, and only a draft claim can be edited.
            </span>
          )}
        </form>
        <ul data-testid="claim-list">
          {mine.map((c) => (
            <ClaimRow
              key={c.id}
              sheetId={sheetId}
              user={user}
              claim={c}
              rate={rateFor(rates, gradeOn(person, c.date), c.date)}
              floor={floor}
              editing={editingId === c.id}
              onEdit={() => openEditor(c)}
              onCancel={cancel}
            />
          ))}
        </ul>
      </td>
    </>
  );
}

/** The sheet's claimed-total: everyone's claimed (OPEN, PENDING and SETTLED claims, but no OPEN or PENDING ones dated within a hold of their person, or of one whose retirement date is reached, and not bound by a statement) added up. */
function ClaimedTotal({ sheetId }: { sheetId: string }) {
  const claims = useClaims(sheetId);
  const people = usePeople(sheetId);
  const today = useSheetToday(sheetId);
  return (
    <p>
      Claimed total <span data-testid="rollup-claimed-total">{total(live(claims.data ?? [], people.data, today))}</span>
      {claims.isError && <span data-testid="claims-load-error"> Could not load claims.</span>}
    </p>
  );
}

export const contributions = [
  PeopleHead.fill({ order: 10, Component: ClaimsHead }),
  PersonRow.fill({ order: 10, Component: PersonClaims }),
  SheetPage.fill({ order: 20, Component: ClaimedTotal }),
];

